import React, { useState } from "react";

function App() {
  const [fullName, setFullName] = useState({
    fname: "",
    lname: "",
  });

  const inputEvent = (event) => {
    const { name, value } = event.target; // Extract `name` and `value` from event.target

    setFullName((preValue) => ({
      ...preValue, // Preserve previous values
      [name]: value, // Update only the changing field dynamically
    }));
  };

  const submit = (event) => {
    event.preventDefault();
  };

  return (
    <>
      <div className="main">
        <form onSubmit={submit}>
          <div className="textarea">
            Hello {fullName.fname} {fullName.lname}
          </div>
          <br />
          <input
            type="text"
            placeholder="Enter Your First Name"
            onChange={inputEvent}
            name="fname"
            value={fullName.fname} // Added controlled input
            className="input"
          />
          <br />
          <br />
          <input
            type="text"
            placeholder="Enter Your Last Name"
            onChange={inputEvent}
            name="lname"
            value={fullName.lname} // Added controlled input
            className="input"
          />
          <br />
          <br />
          <button type="submit" className="btn">
            Submit
          </button>
        </form>
      </div>
    </>
  );
}

export default App;
